MATCH (c:Company) 
WHERE c.name = 'PENAM' OR 'PENAM' IN c.aliases 
RETURN c.launch_year AS launch_year;

MATCH (parent:Company {name: "Groupe Flammarion"})<-[:subsidiaryOf]-(sub:Company)
OPTIONAL MATCH (sub)-[:foundedBy]->(founder:Person)
RETURN sub.name AS subsidiary, count(DISTINCT founder) AS founders_count;

MATCH (c:Company)-[:hasBoardMember]->(p:Person)
WHERE toLower(p.name) = toLower("John Alexander Thain")
RETURN DISTINCT c.name AS companyName;

MATCH (c:Company)
WHERE EXISTS { (c)-[:hasCEO]->(:Person {name:'Andreas Sommer'}) }
   OR EXISTS { (c)-[:foundedBy]->(:Person {name:'Ita Wegman'}) }
RETURN count(DISTINCT c) AS company_count;

MATCH (c:Company)-[:operatesIn]->(i:Industry), (c)-[:foundedBy]->(p:Person)  
WHERE toLower(i.name) CONTAINS 'footwear'                      
RETURN DISTINCT p.name AS founder, p.gender AS gender;

MATCH (c:Company)-[:basedIn]->(co:Country), (c)-[:hasBoardMember]->(p:Person)
WHERE co.name = "United States of America" AND p.name = "Hiro Kamezawa"
RETURN c.name AS company_name, c.launch_year AS launch_year;
